class Solution {
    long long MOD = 1000000007;

    long long power(long long base, long long exp) {
        long long result = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp & 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

public:
    int countGoodArrays(int n, int m, int k) {
        long long N = n - 1;
        long long K = k;

        long long fact = 1;
        long long factK = 1;
        long long factNK = 1;

        for (long long i = 1; i <= N; i++) {
            fact = fact * i % MOD;
            if (i == K) factK = fact;
            if (i == N - K) factNK = fact;
        }

        long long invFactK = power(factK, MOD - 2);
        long long invFactNK = power(factNK, MOD - 2);
        long long comb = fact * invFactK % MOD * invFactNK % MOD;

        long long powM1 = power(m - 1, N - K);

        long long ans = (long long)m % MOD * comb % MOD * powM1 % MOD;
        return (int)ans;
    }
};
